// ────────────────────────────────────────────────────────────────────
// Server-side helper: runs the loop programmatically against Gemini /
// Lovable AI Gateway. Used by zerlal-scan and code-narrative-fix.
// ────────────────────────────────────────────────────────────────────
export interface CodeFile { path: string; content: string }
export interface FlawFinding {
  severity: "critical" | "high" | "medium" | "low" | "info";
  category: string;
  file: string;
  line?: number;
  title: string;
  explanation: string;
}
export interface IterationResult {
  iteration: number;
  narrative: string;
  flaws: FlawFinding[];
  patched_files?: CodeFile[];
  before_after?: Array<{ path: string; before: string; after: string; behavior_after: string }>;
}

type AIKeys = { lovableKey?: string; geminiKey?: string };

async function callJsonAI(prompt: string, keys: AIKeys): Promise<any> {
  // Try Lovable Gateway first
  if (keys.lovableKey) {
    try {
      const r = await fetch("https://ai.gateway.lovable.dev/v1/chat/completions", {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${keys.lovableKey}` },
        body: JSON.stringify({
          model: "google/gemini-flash-latest",
          messages: [
            { role: "system", content: "Return ONLY valid JSON. No markdown fences." },
            { role: "user", content: prompt },
          ],
          temperature: 0.1,
          max_tokens: 16000,
        }),
      });
      if (r.ok) {
        const j = await r.json();
        return parseJson(j.choices?.[0]?.message?.content || "");
      }
      if (r.status === 402) throw new Error("AI credits exhausted");
    } catch (e: any) {
      if (String(e?.message).includes("credits")) throw e;
      // fall through
    }
  }
  if (keys.geminiKey) {
    const r = await fetch(
      `https://generativelanguage.googleapis.com/v1beta/models/gemini-flash-latest:generateContent?key=${keys.geminiKey}`,
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          contents: [{ parts: [{ text: prompt }] }],
          generationConfig: { temperature: 0.1, maxOutputTokens: 16000, responseMimeType: "application/json" },
        }),
      },
    );
    if (!r.ok) throw new Error(`Gemini ${r.status}: ${(await r.text()).slice(0, 200)}`);
    const j = await r.json();
    return parseJson(j.candidates?.[0]?.content?.parts?.[0]?.text || "");
  }
  throw new Error("No AI key available for narrative loop");
}

function parseJson(text: string): any {
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const candidate = fenced?.[1] || text;
  const m = candidate.match(/\{[\s\S]*\}/);
  if (!m) throw new Error("No JSON in model response");
  try {
    return JSON.parse(m[0]);
  } catch {
    return JSON.parse(m[0].replace(/,\s*}/g, "}").replace(/,\s*\]/g, "]"));
  }
}

function joinFiles(files: CodeFile[], cap = 80_000): string {
  let out = "";
  for (const f of files) {
    const chunk = `\n--- FILE: ${f.path} ---\n${f.content}\n`;
    if (out.length + chunk.length > cap) break;
    out += chunk;
  }
  return out;
}

export async function runNarrativeLoop(opts: {
  files: CodeFile[];
  instruction?: string;
  keys: AIKeys;
  fix: boolean;
  maxIterations?: number;
}): Promise<{ iterations: IterationResult[]; final_files: CodeFile[]; verdict: string }> {
  const maxIter = Math.min(6, Math.max(1, opts.maxIterations ?? 6));
  const iterations: IterationResult[] = [];
  let currentFiles = opts.files.map((f) => ({ ...f }));

  for (let i = 1; i <= maxIter; i++) {
    const prompt = `${HYPOTHETICAL_REALISM_DOCTRINE}

${CODE_NARRATIVE_PROTOCOL}

${QUANTUM_ORCHESTRATION_BRAIN}

${THEME_ENGINE_DOCTRINE}

You are running the CODE → NARRATIVE → FLAWS${opts.fix ? " → FIX" : ""} loop, iteration ${i} of ${maxIter}. Apply Quantum Candidate Collapse: internally generate 3 candidate fixes per flaw, collapse to the highest-fidelity one before emitting. For any UI/frontend file, additionally enforce the THEME ENGINE DOCTRINE (DNA → Intent → Behavior) and run the Anti-Slop Verification before accepting the fix.

USER INSTRUCTION: ${opts.instruction || "(none — perform full audit)"}

Step A: Read the files and produce a tight narrative summary (1 short paragraph per file, max 8 files mentioned).
Step B: List every flaw (severity critical/high/medium/low/info). Categories: logic, security, ui, workflow, bug, other.
${opts.fix ? "Step C: For every medium+ flaw, produce a fixed version of the affected file (full content) and a one-sentence behavior_after note." : ""}

Return STRICT JSON:
{
  "narrative": "string",
  "flaws": [{"severity":"...","category":"...","file":"...","line":0,"title":"...","explanation":"..."}]${opts.fix ? `,
  "patched_files": [{"path":"...","content":"...full fixed file..."}],
  "before_after": [{"path":"...","before":"...snippet...","after":"...snippet...","behavior_after":"..."}]` : ""}
}

CODE:
\`\`\`
${joinFiles(currentFiles)}
\`\`\``;

    const res = await callJsonAI(prompt, opts.keys);
    const iter: IterationResult = {
      iteration: i,
      narrative: res.narrative || "",
      flaws: Array.isArray(res.flaws) ? res.flaws : [],
      patched_files: Array.isArray(res.patched_files) ? res.patched_files : undefined,
      before_after: Array.isArray(res.before_after) ? res.before_after : undefined,
    };
    iterations.push(iter);

    // Apply patches for next iteration
    if (opts.fix && iter.patched_files?.length) {
      const map = new Map(currentFiles.map((f) => [f.path, f]));
      for (const p of iter.patched_files) {
        if (p?.path && typeof p.content === "string") map.set(p.path, { path: p.path, content: p.content });
      }
      currentFiles = Array.from(map.values());
    }

    // Stop early if no medium+ flaws remain
    const remaining = iter.flaws.filter((f) => ["critical", "high", "medium"].includes(f.severity));
    if (remaining.length === 0) break;
    if (!opts.fix) break; // single pass when only auditing
  }

  const lastFlaws = iterations[iterations.length - 1]?.flaws || [];
  const residual = lastFlaws.filter((f) => ["critical", "high", "medium"].includes(f.severity));
  const verdict = residual.length === 0
    ? "Clean — no medium-or-higher flaws remain."
    : `${residual.length} medium+ flaw(s) still residual after ${iterations.length} iteration(s).`;

  return { iterations, final_files: currentFiles, verdict };
}
